CREATE TABLE PRICE_LOG (
    ITEM_ID    CHAR(4),
    OLD_PRICE  DECIMAL(7,2),
    NEW_PRICE  DECIMAL(7,2),
    CHANGED_ON DATE
);

CREATE TRIGGER LOG_PRICE_CHANGE
AFTER UPDATE OF PRICE ON ITEM
BEGIN
    INSERT INTO PRICE_LOG
    VALUES (OLD.ITEM_ID, OLD.PRICE, NEW.PRICE, DATE('now'));
END;

